CREATE TABLE IF NOT EXISTS schema_versions(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS profiles(user_id TEXT PRIMARY KEY REFERENCES users(id), role TEXT NOT NULL DEFAULT 'player' CHECK(role IN ('player','moderator','admin')), banned INTEGER NOT NULL DEFAULT 0 CHECK(banned IN (0,1)), muted_until BIGINT NOT NULL DEFAULT 0, joined BIGINT NOT NULL, faction TEXT NOT NULL DEFAULT 'pioneers', email TEXT, verified INTEGER NOT NULL DEFAULT 0, totp TEXT, totp_last BIGINT NOT NULL DEFAULT -1);
CREATE UNIQUE INDEX IF NOT EXISTS profile_email_unique ON profiles(lower(email));
CREATE TABLE IF NOT EXISTS alliances(id TEXT PRIMARY KEY, tag TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, leader TEXT NOT NULL REFERENCES users(id), created BIGINT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS alliances_tag_unique ON alliances(lower(tag));
CREATE TABLE IF NOT EXISTS members(user_id TEXT PRIMARY KEY REFERENCES users(id), alliance_id TEXT NOT NULL REFERENCES alliances(id), role TEXT NOT NULL CHECK(role IN ('leader','officer','member')));
CREATE TABLE IF NOT EXISTS invites(id TEXT PRIMARY KEY, alliance_id TEXT NOT NULL REFERENCES alliances(id), user_id TEXT NOT NULL REFERENCES users(id), UNIQUE(alliance_id,user_id));
CREATE TABLE IF NOT EXISTS diplomacy(a TEXT NOT NULL REFERENCES alliances(id), b TEXT NOT NULL REFERENCES alliances(id), status TEXT NOT NULL CHECK(status IN ('nap','war')), proposed_by TEXT NOT NULL REFERENCES alliances(id), accepted INTEGER NOT NULL CHECK(accepted IN (0,1)), PRIMARY KEY(a,b), CHECK(a<b));
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, sender TEXT NOT NULL REFERENCES users(id), channel TEXT NOT NULL CHECK(channel IN ('world','alliance','private')), recipient TEXT, body TEXT NOT NULL, created BIGINT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN (0,1)));
CREATE INDEX IF NOT EXISTS messages_feed ON messages(channel,recipient,created);
CREATE TABLE IF NOT EXISTS mail_reads(user_id TEXT NOT NULL REFERENCES users(id), message_id TEXT NOT NULL REFERENCES messages(id), PRIMARY KEY(user_id,message_id));
CREATE TABLE IF NOT EXISTS offers(id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), give_resource INTEGER NOT NULL CHECK(give_resource BETWEEN 0 AND 2), give_amount INTEGER NOT NULL CHECK(give_amount>0), want_resource INTEGER NOT NULL CHECK(want_resource BETWEEN 0 AND 2), want_amount INTEGER NOT NULL CHECK(want_amount>0), created BIGINT NOT NULL, expires BIGINT NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','filled','cancelled')), buyer TEXT REFERENCES users(id), CHECK(give_resource<>want_resource));
CREATE INDEX IF NOT EXISTS offers_open ON offers(status,expires);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, details TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS flags(name TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, name TEXT NOT NULL, starts BIGINT NOT NULL, ends BIGINT NOT NULL CHECK(ends>starts), bonus INTEGER NOT NULL CHECK(bonus BETWEEN 0 AND 100));
CREATE TABLE IF NOT EXISTS seasons(id TEXT PRIMARY KEY, name TEXT NOT NULL, starts BIGINT NOT NULL, ends BIGINT NOT NULL CHECK(ends>starts), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), standings TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS worker_status(id INTEGER PRIMARY KEY CHECK(id=1), heartbeat BIGINT NOT NULL, error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS job_failures(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), job_id TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 1, error TEXT NOT NULL, created BIGINT NOT NULL, UNIQUE(user_id,job_id));
CREATE TABLE IF NOT EXISTS auth_tokens(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), purpose TEXT NOT NULL CHECK(purpose IN ('verify','reset')), expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','sent','failed')), attempts INTEGER NOT NULL DEFAULT 0, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(bucket TEXT PRIMARY KEY, starts BIGINT NOT NULL, count INTEGER NOT NULL CHECK(count>0));
